1	/*
2	 * boot_main.c - BK7258 Tier-1 bootloader C main.
3	 *
4	 *   uint32_t c_main(void);
5	 *
6	 * Responsibilities (Tier-1 features I / A, with J handled by start.S):
7	 *   I  UART1 logging of boot progress.
8	 *   A  FAL partition table parse -> locate "app", derive its logical address.
9	 *      App header validation (MSP / Reset Thumb / "BK7236\0\0" magic).
10	 * On success c_main prints "jump to:0x02010000\r\n", "JMP\r\n" and returns
11	 * the app logical vector address (e.g. 0x02010000). On failure it prints
12	 * "BAD\r\n" plus a short reason and loops forever (never returns).
13	 *
14	 * The app logical address equals FLASH_BASE + partition.offset, so the same
15	 * scan works if the table is later moved to a real flash partition.
16	 *
17	 * Freestanding: no libc, no mutable globals -> no .bss zeroing needed by
18	 * c_main (start.S calls c_main directly without a C runtime startup).
19	 */
20	
21	#include <stdint.h>
22	#include <stddef.h>
23	
24	/* ------------------------------------------------------------------ */
25	/* MMIO: BK7258 UART1 (matches the verified init in start.S).         */
26	/* ------------------------------------------------------------------ */
27	#define UART1_FIFO_ADDR   0x4583001Cu
28	#define UART1_STATUS_ADDR 0x45830018u
29	#define UART1_TX_READY    (1u << 20)   /* bit20: TX-FIFO-not-full (assumed) */
30	
31	#define REG32(addr)       (*(volatile uint32_t *)(addr))
32	#define UART1_FIFO        REG32(UART1_FIFO_ADDR)
33	#define UART1_STATUS      REG32(UART1_STATUS_ADDR)
34	
35	/* ------------------------------------------------------------------ */
36	/* FAL partition table (mirrors struct fal_partition from the BK SDK,  */
37	/* fal_def.h: magic_word/name[24]/flash_name[24]/offset/len/reserved, */
38	/* 64 bytes per entry). XIP-readable const in .rodata.                 */
39	/* ------------------------------------------------------------------ */
40	#define FAL_DEV_NAME_MAX  24
41	#define FAL_PART_MAGIC    0x45503130u   /* 'E','P','1','0' (fal_partition.c) */
42	
43	#define FLASH_BASE        0x02000000u
44	
45	struct fal_partition {
46	    uint32_t magic_word;
47	    char     name[FAL_DEV_NAME_MAX];
48	    char     flash_name[FAL_DEV_NAME_MAX];
49	    long     offset;        /* logical offset on flash device */
50	    size_t   len;
51	    uint32_t reserved;
52	};
53	
54	__attribute__((used))
55	const struct fal_partition fal_partition_table[] = {
56	    { FAL_PART_MAGIC, "bootloader", "beken_onchip_crc", 0x00000L, 0x10000L, 0u },
57	    { FAL_PART_MAGIC, "app",        "beken_onchip_crc", 0x10000L, 0x10000L, 0u },
58	};
59	#define FAL_PART_COUNT  (sizeof(fal_partition_table) / sizeof(fal_partition_table[0]))
60	
61	/* ------------------------------------------------------------------ */
62	/* UART output (self-implemented; correct nibble order, no v>>32 UB).  */
63	/* ------------------------------------------------------------------ */
64	static void uart_putc(char c)
65	{
66	    /*
67	     * Poll bit20 (TX-FIFO-not-full). The poll is bounded: if the bit polarity
68	     * is ever inverted on silicon, we degrade gracefully to the same
69	     * write-through behavior the verified minimal bootloader used, rather
70	     * than hanging the boot.
71	     */
72	    for (int i = 0; i < 100000; i++) {
73	        if (UART1_STATUS & UART1_TX_READY) {
74	            break;
75	        }
76	    }
77	    UART1_FIFO = (uint32_t)(uint8_t)c;
78	}
79	
80	static void uart_puts(const char *s)
81	{
82	    while (*s) {
83	        uart_putc(*s++);
84	    }
85	}
86	
87	static void print_hex32(uint32_t v)
88	{
89	    static const char hex[] = "0123456789ABCDEF";
90	    int s;
91	    /* for(s=28; s>=0; s-=4): avoids the v>>32 undefined behaviour that the
92	       earlier probe fell into (top nibble got shifted into oblivion). */
93	    for (s = 28; s >= 0; s -= 4) {
94	        uart_putc(hex[(v >> s) & 0xFu]);
95	    }
96	}
97	
98	static void log_u32(const char *label, uint32_t value)
99	{
100	    uart_puts(label);
101	    uart_puts("0x");
102	    print_hex32(value);
103	    uart_puts("\r\n");
104	}
105	
106	/* ------------------------------------------------------------------ */
107	/* Partition scan + helpers.                                          */
108	/* ------------------------------------------------------------------ */
109	static int name_eq(const char *a, const char *b)
110	{
111	    int i;
112	    for (i = 0; i < FAL_DEV_NAME_MAX; i++) {
113	        if (a[i] != b[i]) {
114	            return 0;
115	        }
116	        if (a[i] == '\0') {
117	            return 1;
118	        }
119	    }
120	    return 1;   /* equal across the full FAL_DEV_NAME_MAX width */
121	}
122	
123	static const struct fal_partition *fal_find(const char *name)
124	{
125	    size_t i;
126	    for (i = 0; i < FAL_PART_COUNT; i++) {
127	        if (fal_partition_table[i].magic_word != FAL_PART_MAGIC) {
128	            continue;
129	        }
130	        if (name_eq(fal_partition_table[i].name, name)) {
131	            return &fal_partition_table[i];
132	        }
133	    }
134	    return (const struct fal_partition *)0;
135	}
136	
137	/* ------------------------------------------------------------------ */
138	/* App header validation (ported from bk7236_min_bl.S to C).          */
139	/* ------------------------------------------------------------------ */
140	static int validate_app(uint32_t app_vec)
141	{
142	    volatile uint32_t *vec   = (volatile uint32_t *)app_vec;
143	    volatile uint32_t *magic = (volatile uint32_t *)(app_vec + 0x100u);
144	    uint32_t msp  = vec[0];
145	    uint32_t rst  = vec[1];
146	
147	    /* MSP must land in SRAM [0x28000000 .. 0x280A0000]. */
148	    if (msp < 0x28000000u || msp > 0x280A0000u) {
149	        uart_puts("BAD\r\nmsp OOR\r\n");
150	        return 0;
151	    }
152	    /* Reset_Handler must have the Thumb bit set. */
153	    if ((rst & 1u) == 0u) {
154	        uart_puts("BAD\r\nreset no-thumb\r\n");
155	        return 0;
156	    }
157	    /* app magic @ app_vec + 0x100 == "BK7236\0\0"
158	       bytes  42 4B 37 32 -> word 0x32374B42
159	              33 36 00 00 -> word 0x00003633 */
160	    if (magic[0] != 0x32374B42u) {
161	        uart_puts("BAD\r\nmagic0\r\n");
162	        return 0;
163	    }
164	    if (magic[1] != 0x00003633u) {
165	        uart_puts("BAD\r\nmagic1\r\n");
166	        return 0;
167	    }
168	    return 1;
169	}
170	
171	/* ------------------------------------------------------------------ */
172	/* C entry called from start.S. Returns app logical vector address.   */
173	/* ------------------------------------------------------------------ */
174	__attribute__((used))
175	uint32_t c_main(void)
176	{
177	    const struct fal_partition *app;
178	    uint32_t app_vec;
179	
180	    uart_puts("u_bootloader enter\r\n");
181	
182	    /* A: FAL partition parse -> find "app". */
183	    app = fal_find("app");
184	    if (app == (const struct fal_partition *)0) {
185	        uart_puts("BAD\r\nno app part\r\n");
186	        for (;;) { }
187	    }
188	    app_vec = FLASH_BASE + (uint32_t)app->offset;
189	    log_u32("partition app @ ", app_vec);
190	
191	    /* Validate app header. */
192	    if (!validate_app(app_vec)) {
193	        for (;;) { }
194	    }
195	
196	    log_u32("jump to:", app_vec);
197	    uart_puts("JMP\r\n");
198	    return app_vec;
199	}
