39	/****************************************************************************
40	 * Pre-processor Definitions
41	 ****************************************************************************/
42	
43	/* First external (device) interrupt number == vector slot 16. */
44	
45	#define BK7258_IRQ_FIRST        16
46	
47	/* NVIC enable/clear register bank stride. */
48	
49	#define NVIC_ENA_OFFSET         (0)
50	#define NVIC_CLRENA_OFFSET      (NVIC_IRQ0_31_CLEAR - NVIC_IRQ0_31_ENABLE)
51	
52	/* Default priority packed four-per-register (one stroke for all 4 slots). */
53	
54	#define DEFPRIORITY32           (NVIC_SYSH_PRIORITY_DEFAULT << 24 | \
55	                                 NVIC_SYSH_PRIORITY_DEFAULT << 16 | \
56	                                 NVIC_SYSH_PRIORITY_DEFAULT << 8  | \
57	                                 NVIC_SYSH_PRIORITY_DEFAULT)
58	
59	/* UART1 MMIO for the boot-trace marker pushed at the top of up_irqinitialize().
60	 * Freestanding polled putc (polls fifo_status.bit20, writes fifo_port);
61	 * identical to start.c::bk7258_early_putc and vectors.c::bk7258_fault_putc.
62	 * Local to this translation unit so it introduces no new linkage dependency.
63	 */
64	
65	#define BK7258_IRQ_UART1_FSTAT  (*(volatile uint32_t *)0x45830018u)
66	#define BK7258_IRQ_UART1_FPORT  (*(volatile uint32_t *)0x4583001Cu)
67	#define BK7258_IRQ_UART1_READY  (1u << 20)
68	
69	/****************************************************************************
70	 * Private Functions
71	 ****************************************************************************/
72	
73	/* Bare MMIO single-byte marker.  Emits 'I' at function entry of
74	 * up_irqinitialize() so board-side observation can confirm the NVIC bring-up
75	 * was reached during the nx_start() walk.
76	 */
77	
78	static void bk7258_irq_diag_putc(unsigned char c)
79	{
80	  while ((BK7258_IRQ_UART1_FSTAT & BK7258_IRQ_UART1_READY) == 0)
81	    {
82	    }
83	
84	  BK7258_IRQ_UART1_FPORT = (uint32_t)(c & 0xffu);
85	}
