87	/****************************************************************************
88	 * Name: bk7258_prioritize_syscall
89	 *
90	 * Description:
91	 *   Set the priority of the SVCall exception (system handler 11).  Needed
92	 *   internally even when CONFIG_ARCH_IRQPRIO is off.
93	 *
94	 ****************************************************************************/
95	
96	static inline void bk7258_prioritize_syscall(int priority)
97	{
98	  uint32_t regval;
99	
100	  regval  = getreg32(NVIC_SYSH8_11_PRIORITY);
101	  regval &= ~NVIC_SYSH_PRIORITY_PR11_MASK;
102	  regval |= (priority << NVIC_SYSH_PRIORITY_PR11_SHIFT);
103	  putreg32(regval, NVIC_SYSH8_11_PRIORITY);
104	}
105	
106	/****************************************************************************
107	 * Public Functions
108	 ****************************************************************************/
109	
110	/****************************************************************************
111	 * Name: up_prioritize_irq
112	 *
113	 * Description:
114	 *   Set the priority of an IRQ.
115	 *
116	 ****************************************************************************/
117	
118	int up_prioritize_irq(int irq, int priority)
119	{
120	  uint32_t regaddr;
121	  uint32_t regval;
122	  int shift;
123	
124	  DEBUGASSERT(irq >= 0 && irq < NR_IRQS &&
125	              (unsigned)priority <= NVIC_SYSH_PRIORITY_MIN);
126	
127	  if (irq < 16)
128	    {
129	      /* NVIC_SYSH_PRIORITY() maps {0..15} to one of the priority registers
130	       * (0-3 are invalid as raw indices; they are remapped internally).
131	       */
132	
133	      regaddr = NVIC_SYSH_PRIORITY(irq);
134	      irq    -= 4;
135	    }
136	  else
137	    {
138	      /* NVIC_IRQ_PRIORITY() maps {0..} to the external priority registers. */
139	
140	      irq    -= 16;
141	      regaddr = NVIC_IRQ_PRIORITY(irq);
142	    }
143	
144	  regval  = getreg32(regaddr);
145	  shift   = ((irq & 3) << 3);
146	  regval &= ~(0xff << shift);
147	  regval |= (priority << shift);
148	  putreg32(regval, regaddr);
149	
150	  return OK;
151	}
