153	/****************************************************************************
154	 * Name: up_irqinitialize
155	 *
156	 * Description:
157	 *   Bring the NVIC up to a known, ready state.  Called from up_initialize().
158	 *
159	 ****************************************************************************/
160	
161	void up_irqinitialize(void)
162	{
163	  uint32_t regaddr;
164	  int num_priority_registers;
165	  int i;
166	
167	  /* Boot-trace marker: reached up_irqinitialize() inside nx_start(). */
168	
169	  bk7258_irq_diag_putc('I');
170	
171	  /* Disable all external interrupts. */
172	
173	  for (i = 0; i < NR_IRQS - BK7258_IRQ_FIRST; i += 32)
174	    {
175	      putreg32(0xffffffff, NVIC_IRQ_CLEAR(i));
176	    }
177	
178	  /* Point VTOR at our flash-resident vector table (also set in __start;
179	   * redundant here but deterministic).
180	   */
181	
182	  putreg32((uint32_t)_vectors, NVIC_VECTAB);
183	
184	#ifdef CONFIG_ARCH_RAMVECTORS
185	  arm_ramvec_initialize();
186	#endif
187	
188	  /* Default-prioritise the system exceptions. */
189	
190	  putreg32(DEFPRIORITY32, NVIC_SYSH4_7_PRIORITY);
191	  putreg32(DEFPRIORITY32, NVIC_SYSH8_11_PRIORITY);
192	  putreg32(DEFPRIORITY32, NVIC_SYSH12_15_PRIORITY);
193	
194	  /* The NVIC ICTR register (bits 0-4) holds (number of IRQ lines / 32) - 1,
195	   * which also tells us how many priority registers to default-fill.
196	   */
197	
198	  num_priority_registers = (getreg32(NVIC_ICTR) + 1) * 8;
199	
200	  regaddr = NVIC_IRQ0_3_PRIORITY;
201	  while (num_priority_registers--)
202	    {
203	      putreg32(DEFPRIORITY32, regaddr);
204	      regaddr += 4;
205	    }
206	
207	  /* Attach the SVCall and HardFault handlers used by the scheduler. */
208	
209	  irq_attach(NVIC_IRQ_SVCALL, arm_svcall, NULL);
210	  irq_attach(NVIC_IRQ_HARDFAULT, arm_hardfault, NULL);
211	
212	  /* PendSV runs at the lowest priority so it never preempts device IRQs. */
213	
214	  up_prioritize_irq(NVIC_IRQ_PENDSV, NVIC_SYSH_PRIORITY_MIN);
215	  bk7258_prioritize_syscall(NVIC_SYSH_SVCALL_PRIORITY);
216	
217	  /* Enable the MemManage fault if the MPU is in use. */
218	
219	#ifdef CONFIG_ARM_MPU
220	  irq_attach(NVIC_IRQ_MEMFAULT, arm_memfault, NULL);
221	  up_enable_irq(NVIC_IRQ_MEMFAULT);
222	#endif
223	
224	#ifndef CONFIG_SUPPRESS_INTERRUPTS
225	
226	  /* Colour the interrupt stack (writes a sentinel pattern) and unmask IRQs. */
227	
228	  arm_color_intstack();
229	  up_irq_enable();
230	#endif
231	}
