233	/****************************************************************************
234	 * Name: bk7258_irqinfo
235	 *
236	 * Description:
237	 *   Map a NuttX IRQ number to the (register, bit) pair that enables/disables
238	 *   it in the NVIC, honouring the enable/clear bank offset for external IRQs
239	 *   and the SYSHCON/SYSTICK control bits for the handful of manageable
240	 *   system exceptions.
241	 *
242	 ****************************************************************************/
243	
244	static int bk7258_irqinfo(int irq, uintptr_t *regaddr, uint32_t *bit,
245	                          uintptr_t offset)
246	{
247	  int n;
248	
249	  DEBUGASSERT(irq >= NVIC_IRQ_NMI && irq < NR_IRQS);
250	
251	  /* External device interrupt? */
252	
253	  if (irq >= BK7258_IRQ_FIRST)
254	    {
255	      n        = irq - BK7258_IRQ_FIRST;
256	      *regaddr = NVIC_IRQ_ENABLE(n) + offset;
257	      *bit     = (uint32_t)0x1 << (n & 0x1f);
258	    }
259	
260	  /* Processor exception -- only a few can be enabled/disabled. */
261	
262	  else
263	    {
264	      *regaddr = NVIC_SYSHCON;
265	      if (irq == NVIC_IRQ_MEMFAULT)
266	        {
267	          *bit = NVIC_SYSHCON_MEMFAULTENA;
268	        }
269	      else if (irq == NVIC_IRQ_BUSFAULT)
270	        {
271	          *bit = NVIC_SYSHCON_BUSFAULTENA;
272	        }
273	      else if (irq == NVIC_IRQ_USAGEFAULT)
274	        {
275	          *bit = NVIC_SYSHCON_USGFAULTENA;
276	        }
277	      else if (irq == NVIC_IRQ_SYSTICK)
278	        {
279	          *regaddr = NVIC_SYSTICK_CTRL;
280	          *bit = NVIC_SYSTICK_CTRL_ENABLE;
281	        }
282	      else
283	        {
284	          return -EINVAL;  /* Invalid or unsupported exception */
285	        }
286	    }
287	
288	  return OK;
289	}
