291	/****************************************************************************
292	 * Name: up_disable_irq
293	 *
294	 ****************************************************************************/
295	
296	void up_disable_irq(int irq)
297	{
298	  uintptr_t regaddr;
299	  uint32_t  regval;
300	  uint32_t  bit;
301	
302	  if (bk7258_irqinfo(irq, &regaddr, &bit, NVIC_CLRENA_OFFSET) == 0)
303	    {
304	      if (irq >= BK7258_IRQ_FIRST)
305	        {
306	          /* External: write 1 to the Clear-Enable bank bit. */
307	
308	          putreg32(bit, regaddr);
309	        }
310	      else
311	        {
312	          /* System exception: clear the SYSHCON / SYSTICK bit. */
313	
314	          regval  = getreg32(regaddr);
315	          regval &= ~bit;
316	          putreg32(regval, regaddr);
317	        }
318	    }
319	}
320	
321	/****************************************************************************
322	 * Name: up_enable_irq
323	 *
324	 ****************************************************************************/
325	
326	void up_enable_irq(int irq)
327	{
328	  uintptr_t regaddr;
329	  uint32_t  regval;
330	  uint32_t  bit;
331	
332	  if (bk7258_irqinfo(irq, &regaddr, &bit, NVIC_ENA_OFFSET) == 0)
333	    {
334	      if (irq >= BK7258_IRQ_FIRST)
335	        {
336	          /* External: write 1 to the Set-Enable bank bit. */
337	
338	          putreg32(bit, regaddr);
339	        }
340	      else
341	        {
342	          /* System exception: set the SYSHCON / SYSTICK bit. */
343	
344	          regval  = getreg32(regaddr);
345	          regval |= bit;
346	          putreg32(regval, regaddr);
347	        }
348	    }
349	}
