88	 * Description:
89	 *   Set the priority of an exception.  This function may be needed
90	 *   internally even if support for prioritized interrupts is not enabled.
91	 *
92	 ****************************************************************************/
93	
94	static inline void mps_prioritize_syscall(int priority)
95	{
96	  uint32_t regval;
97	
98	  /* SVCALL is system handler 11 */
99	
100	  regval  = getreg32(NVIC_SYSH8_11_PRIORITY);
101	  regval &= ~NVIC_SYSH_PRIORITY_PR11_MASK;
102	  regval |= (priority << NVIC_SYSH_PRIORITY_PR11_SHIFT);
103	  putreg32(regval, NVIC_SYSH8_11_PRIORITY);
104	}
