110	/****************************************************************************
111	 * Name: up_prioritize_irq
112	 *
113	 * Description:
114	 *  Set the priority of an IRQ.  This function may be needed internally
115	 *  even if support for prioritized interrupts is not enabled.
116	 *
117	 ****************************************************************************/
118	
119	int up_prioritize_irq(int irq, int priority)
120	{
121	  uint32_t regaddr;
122	  uint32_t regval;
123	  int shift;
124	
125	  DEBUGASSERT(irq >= 0 && irq < NR_IRQS &&
126	              (unsigned)priority <= NVIC_SYSH_PRIORITY_MIN);
127	
128	  if (irq < 16)
129	    {
130	      /* NVIC_SYSH_PRIORITY() maps {0..15} to one of three priority
131	       * registers (0-3 are invalid)
132	       */
133	
134	      regaddr = NVIC_SYSH_PRIORITY(irq);
135	      irq    -= 4;
136	    }
137	  else
138	    {
139	      /* NVIC_IRQ_PRIORITY() maps {0..} to one of many priority registers */
140	
141	      irq    -= 16;
142	      regaddr = NVIC_IRQ_PRIORITY(irq);
143	    }
144	
145	  regval      = getreg32(regaddr);
146	  shift       = ((irq & 3) << 3);
147	  regval     &= ~(0xff << shift);
148	  regval     |= (priority << shift);
149	  putreg32(regval, regaddr);
150	
151	  return OK;
152	}
