154	/****************************************************************************
155	 * Name: up_irqinitialize
156	 *
157	 * Description:
158	 *   This function is called by up_initialize() during the bring-up of the
159	 *   system.  It is the responsibility of this function to but the interrupt
160	 *   subsystem into the working and ready state.
161	 *
162	 ****************************************************************************/
163	
164	void up_irqinitialize(void)
165	{
166	  uint32_t regaddr;
167	  int num_priority_registers;
168	  int i;
169	
170	  /* Disable all interrupts */
171	
172	  for (i = 0; i < NR_IRQS - MPS_IRQ_FIRST; i += 32)
173	    {
174	      putreg32(0xffffffff, NVIC_IRQ_CLEAR(i));
175	    }
176	
177	  putreg32((uint32_t)_vectors, NVIC_VECTAB);
178	
179	#ifdef CONFIG_ARCH_RAMVECTORS
180	  /* If CONFIG_ARCH_RAMVECTORS is defined, then we are using a RAM-based
181	   * vector table that requires special initialization.
182	   */
183	
184	  arm_ramvec_initialize();
185	#endif
186	
187	  /* Set all interrupts (and exceptions) to the default priority */
188	
189	  putreg32(DEFPRIORITY32, NVIC_SYSH4_7_PRIORITY);
190	  putreg32(DEFPRIORITY32, NVIC_SYSH8_11_PRIORITY);
191	  putreg32(DEFPRIORITY32, NVIC_SYSH12_15_PRIORITY);
192	
193	  /* The NVIC ICTR register (bits 0-4) holds the number of of interrupt
194	   * lines that the NVIC supports:
195	   *
196	   *  0 -> 32 interrupt lines,  8 priority registers
197	   *  1 -> 64 "       " "   ", 16 priority registers
198	   *  2 -> 96 "       " "   ", 32 priority registers
199	   *  ...
200	   */
201	
202	  num_priority_registers = (getreg32(NVIC_ICTR) + 1) * 8;
203	
204	  /* Now set all of the interrupt lines to the default priority */
205	
206	  regaddr = NVIC_IRQ0_3_PRIORITY;
207	  while (num_priority_registers--)
208	    {
209	      putreg32(DEFPRIORITY32, regaddr);
210	      regaddr += 4;
211	    }
212	
213	  /* Attach the SVCall and Hard Fault exception handlers.  The SVCall
214	   * exception is used for performing context switches; The Hard Fault
215	   * must also be caught because a SVCall may show up as a Hard Fault
216	   * under certain conditions.
217	   */
218	
219	  irq_attach(MPS_IRQ_SVCALL, arm_svcall, NULL);
220	  irq_attach(MPS_IRQ_HARDFAULT, arm_hardfault, NULL);
221	
222	  /* Set the priority of the SVCall interrupt */
223	
224	  up_prioritize_irq(MPS_IRQ_PENDSV, NVIC_SYSH_PRIORITY_MIN);
225	
226	  mps_prioritize_syscall(NVIC_SYSH_SVCALL_PRIORITY);
227	
228	  /* If the MPU is enabled, then attach and enable the Memory Management
229	   * Fault handler.
230	   */
231	
232	#ifdef CONFIG_ARM_MPU
233	  irq_attach(MPS_IRQ_MEMFAULT, arm_memfault, NULL);
234	  up_enable_irq(MPS_IRQ_MEMFAULT);
235	#endif
236	
237	  /* Attach all other processor exceptions (except reset and sys tick) */
238	
239	#ifdef CONFIG_DEBUG_FEATURES
240	  irq_attach(MPS_IRQ_NMI, mps_nmi, NULL);
241	#ifndef CONFIG_ARM_MPU
242	  irq_attach(MPS_IRQ_MEMFAULT, arm_memfault, NULL);
243	#endif
244	  irq_attach(MPS_IRQ_BUSFAULT, arm_busfault, NULL);
245	  irq_attach(MPS_IRQ_USAGEFAULT, arm_usagefault, NULL);
246	  irq_attach(MPS_IRQ_PENDSV, mps_pendsv, NULL);
247	  irq_attach(MPS_IRQ_DBGMONITOR, arm_dbgmonitor, NULL);
248	  irq_attach(MPS_IRQ_RESERVED, mps_reserved, NULL);
249	#endif
250	
251	#ifndef CONFIG_SUPPRESS_INTERRUPTS
252	
253	  /* And finally, enable interrupts */
254	
255	  arm_color_intstack();
256	  up_irq_enable();
257	#endif
258	}
