260	static int mps_irqinfo(int irq, uintptr_t *regaddr, uint32_t *bit,
261	                             uintptr_t offset)
262	{
263	  int n;
264	
265	  DEBUGASSERT(irq >= MPS_IRQ_NMI && irq < NR_IRQS);
266	
267	  /* Check for external interrupt */
268	
269	  if (irq >= MPS_IRQ_FIRST)
270	    {
271	      n        = irq - MPS_IRQ_FIRST;
272	      *regaddr = NVIC_IRQ_ENABLE(n) + offset;
273	      *bit     = (uint32_t)0x1 << (n & 0x1f);
274	    }
275	
276	  /* Handle processor exceptions.  Only a few can be disabled */
277	
278	  else
279	    {
280	      *regaddr = NVIC_SYSHCON;
281	      if (irq == MPS_IRQ_MEMFAULT)
282	        {
283	          *bit = NVIC_SYSHCON_MEMFAULTENA;
284	        }
285	      else if (irq == MPS_IRQ_BUSFAULT)
286	        {
287	          *bit = NVIC_SYSHCON_BUSFAULTENA;
288	        }
289	      else if (irq == MPS_IRQ_USAGEFAULT)
290	        {
291	          *bit = NVIC_SYSHCON_USGFAULTENA;
292	        }
293	      else if (irq == MPS_IRQ_SYSTICK)
294	        {
295	          *regaddr = NVIC_SYSTICK_CTRL;
296	          *bit = NVIC_SYSTICK_CTRL_ENABLE;
297	        }
298	      else
299	        {
300	          return -EINVAL; /* Invalid or unsupported exception */
301	        }
302	    }
303	
304	  return OK;
305	}
