307	/****************************************************************************
308	 * Name: up_disable_irq
309	 *
310	 * Description:
311	 *   Disable the IRQ specified by 'irq'
312	 *
313	 ****************************************************************************/
314	
315	void up_disable_irq(int irq)
316	{
317	  uintptr_t regaddr;
318	  uint32_t regval;
319	  uint32_t bit;
320	
321	  if (mps_irqinfo(irq, &regaddr, &bit, NVIC_CLRENA_OFFSET) == 0)
322	    {
323	      /* Modify the appropriate bit in the register to disable the interrupt.
324	       * For normal interrupts, we need to set the bit in the associated
325	       * Interrupt Clear Enable register.  For other exceptions, we need to
326	       * clear the bit in the System Handler Control and State Register.
327	       */
328	
329	      if (irq >= MPS_IRQ_FIRST)
330	        {
331	          putreg32(bit, regaddr);
332	        }
333	      else
334	        {
335	          regval  = getreg32(regaddr);
336	          regval &= ~bit;
337	          putreg32(regval, regaddr);
338	        }
339	    }
340	}
