357	    {
358	      /* Modify the appropriate bit in the register to enable the interrupt.
359	       * For normal interrupts, we need to set the bit in the associated
360	       * Interrupt Set Enable register.  For other exceptions, we need to
361	       * set the bit in the System Handler Control and State Register.
362	       */
